#!/usr/bin/env node

const { version } = require('../package.json');

const args = process.argv.slice(2);

if (args.length === 1 && args[0] === '--version') {
  console.log(version);
} else {
  console.log(`Hello, ${args[0] || 'world'}!`);
}
{
  "name": "greet",
  "version": "0.1.0",
  "private": true,
  "bin": {
    "greet": "bin/greet.js"
  }
}
const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const path = require('node:path');
const test = require('node:test');

const cli = path.join(__dirname, '..', 'bin', 'greet.js');

test('greets a named person', () => {
  assert.equal(execFileSync(process.execPath, [cli, 'Mike'], { encoding: 'utf8' }), 'Hello, Mike!\n');
});

test('greets the world when no name is given', () => {
  assert.equal(execFileSync(process.execPath, [cli], { encoding: 'utf8' }), 'Hello, world!\n');
});

test('prints the declared package version', () => {
  const { version } = require('../package.json');
  assert.equal(execFileSync(process.execPath, [cli, '--version'], { encoding: 'utf8' }), `${version}\n`);
});
